SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱高炽", "aliases": ["明仁宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明仁宗，永樂22年（1424年）八月，朱高炽即皇帝位。", "biography": null, "status": "draft", "id": "2dded14d-7183-56b5-9029-ca93826c1e80"}, {"name": "李景隆", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "曹国公。本纪记其在建文元年继耿炳文后为征虏大将军。", "biography": null, "status": "draft", "id": "74bfbb9a-13ef-5b0a-8ce8-2e9f902907af"}, {"name": "朱棣", "aliases": ["明成祖"], "era": "明", "birth_year": null, "death_year": null, "description": "明成祖，建文4年（1402年），朱棣即皇帝位。", "biography": null, "status": "draft", "id": "dd806a37-77e8-5244-96e9-4d71db81b600"}, {"name": "朱高煦", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "汉王。宣德元年（年号对照1426年），本表记录了朱高煦的活动。", "biography": null, "status": "draft", "id": "b6d6c246-3315-52c1-b7c1-e0ebc937a6ce"}, {"name": "朱瞻基", "aliases": ["明宣宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明宣宗，洪熙元年（1425年）六月，朱瞻基即皇帝位。", "biography": null, "status": "draft", "id": "888fc961-674c-52bf-b645-1351d5637434"}, {"name": "夏原吉", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，建文4年（年号对照1402年）九月，夏原吉出任户部尚书。", "biography": null, "status": "draft", "id": "1f881ca5-40e5-5578-8f0a-653eb82f0a44"}, {"name": "吴中", "aliases": ["吳中"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，永乐2年（年号对照1404年）九月，吴中出任右都御史。", "biography": null, "status": "draft", "id": "322e138f-8e05-53df-89d6-67fa82c7457a"}, {"name": "郑亨", "aliases": ["武安侯"], "era": "明", "birth_year": null, "death_year": null, "description": "郑亨以武安侯身份率领中军。", "biography": null, "status": "draft", "id": "c500cb31-5132-5a9b-8600-28aa5c7f9ee8"}, {"name": "朱荣", "aliases": ["朱仲华"], "era": "明", "birth_year": null, "death_year": null, "description": "朱荣领兵担任前锋。", "biography": null, "status": "draft", "id": "7c50ae9b-791a-520b-9a9b-f076a35ad63f"}, {"name": "杨荣", "aliases": ["楊榮"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，建文4年（1402年）九月，杨荣以翰林修撰身份入直文渊阁。", "biography": null, "status": "draft", "id": "3da8dec2-a076-58ad-bf6e-5271a8173343"}, {"name": "金幼孜", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，建文4年（1402年）九月，金幼孜以翰林检讨身份入直文渊阁。", "biography": null, "status": "draft", "id": "01f8c39e-a2e9-5539-9e26-8926e64fc703"}, {"name": "杨士奇", "aliases": ["楊士奇"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，建文4年（1402年）九月，杨士奇以翰林编修身份入直文渊阁。", "biography": null, "status": "draft", "id": "cf93d13f-f48a-5fc6-8687-47933c0ca559"}, {"name": "黄淮", "aliases": ["黃淮"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，建文4年（1402年）八月，黄淮以翰林编修身份入直文渊阁。", "biography": null, "status": "draft", "id": "e32b0e82-1f00-53e4-bd5e-1b46eecf09ef"}, {"name": "杨溥（明代内阁大学士）", "aliases": ["楊溥"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，洪熙元年（1425年）闰七月，杨溥以太常卿兼翰林学士身份共同处理内阁事务。", "biography": null, "status": "draft", "id": "1f1bfa42-5ca4-5450-84a8-f7927b05b3f7"}, {"name": "黎利", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "黎利在交阯起兵。", "biography": null, "status": "draft", "id": "c3cb3b52-845e-5798-86eb-c3dfdd072dcd"}, {"name": "黄福", "aliases": ["黃福"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，建文4年（年号对照1402年）九月，黄福出任工部尚书。", "biography": null, "status": "draft", "id": "ca18f275-1926-5443-888b-803875e92624"}, {"name": "王彰（明代官员）", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，永乐18年（年号对照1420年）十二月，王彰出任右都御史。", "biography": null, "status": "draft", "id": "a5ac1cd4-66d4-5c79-a4fd-99a903adc6df"}, {"name": "吕震（明代官员）", "aliases": [], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，永乐3年（年号对照1405年）九月，吕震出任刑部尚书。", "biography": null, "status": "draft", "id": "d58bc9ab-d97e-592e-909f-284f788a262a"}, {"name": "蹇义", "aliases": ["蹇義"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，建文4年（年号对照1402年）九月，蹇义出任吏部尚书。", "biography": null, "status": "draft", "id": "9ba158c7-e385-515d-a04d-b17a7bb11a0a"}, {"name": "张氏（明仁宗诚孝昭皇后）", "aliases": ["诚孝昭皇后"], "era": "明", "birth_year": null, "death_year": null, "description": "张氏是朱高炽的妃，朱高炽即位后册立她为皇后。", "biography": null, "status": "draft", "id": "d98838f2-35b9-58ff-8f19-a2588ec64e18"}, {"name": "阿鲁台", "aliases": ["和宁王"], "era": "明", "birth_year": null, "death_year": null, "description": "阿鲁台受封和宁王。", "biography": null, "status": "draft", "id": "fd6d854f-724b-5621-91d3-593e412f448b"}, {"name": "徐氏", "aliases": ["仁孝皇后", "仁孝文皇后"], "era": "明", "birth_year": null, "death_year": null, "description": "徐氏安葬于长陵。", "biography": null, "status": "draft", "id": "c6b4fefb-6944-582a-a23c-c1463d3b3963"}]'::jsonb)
