INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朱高炽被册为燕王世子", "description": "洪武二十八年，朝廷册立朱高炽为燕王世子。 按原历纪年，事情发生在公元1395至1396年之间。", "start_year": null, "end_year": null, "time_original": "洪武二十八年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7c394879-019c-5124-a6ea-e8ceee36421c"}, {"title": "李景隆围攻北平，燕军回援", "description": "李景隆率部围攻北平，燕军返回救援。", "start_year": 1399, "end_year": 1399, "time_original": "建文元年十月辛亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "58a4e28e-a087-5583-acaf-64ca0ccc71f8"}, {"title": "朱高炽未拆朝廷来信，派人转交父亲", "description": "靖难期间，朝廷写信给燕王世子朱高炽，试图离间父子。黄俨先向朱棣报告世子与朝廷有联络，但朱高炽没有开封，直接派人将信交给朱棣。", "start_year": null, "end_year": null, "time_original": "靖难期间，具体年月未载", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c2a2fdd3-61c7-53e1-afe8-9cbd9f7dc8d1"}, {"title": "汉王朱高煦获罪改封乐安州", "description": "永乐十五年三月丙午，汉王朱高煦获罪，朝廷将他的封地改至乐安州。", "start_year": 1417, "end_year": 1417, "time_original": "永乐十五年三月丙午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a2c113c7-a68a-55a5-9525-447fef41f054"}, {"title": "黄俨等告发皇太子，东宫多名官员被追责身亡", "description": "卷八记永乐十六年，黄俨等人指控皇太子朱高炽擅自赦免罪人，东宫多名官员因而被治罪身亡。 按原历纪年，事情发生在公元1418至1419年之间。", "start_year": null, "end_year": null, "time_original": "永乐十六年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e0c934d1-663b-501a-9e47-980ee7ed967a"}, {"title": "胡濙调查后密奏，朱棣对皇太子的疑虑缓解", "description": "皇太子受到指控后，侍郎胡濙奉命调查，秘密上奏太子诚敬孝谨的七件事。朱棣的疑虑由此缓解。", "start_year": null, "end_year": null, "time_original": "黄俨等指控太子之后", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3add27fa-e7a2-5a60-8f9c-63169a9c96b2"}, {"title": "黄俨等谋立朱高燧事发，皇太子力为朱高燧解说", "description": "卷八记载，后来黄俨等人谋立朱高燧，事发后被处死。皇太子朱高炽尽力为朱高燧解说，朱高燧因此免于获罪。", "start_year": null, "end_year": null, "time_original": "胡濙调查以后，具体年月待核", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c300d4dd-58b0-5ac4-8d19-a8106af42e59"}, {"title": "明成祖朱棣在榆木川去世", "description": "永乐二十二年七月辛卯，明成祖朱棣在榆木川去世，本纪记其享年六十五。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年七月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d85ed957-25d7-5fc1-86b1-f3e0ed0ae4d7"}, {"title": "杨荣等抵京，皇太子遣皇太孙往开平迎灵", "description": "永乐二十二年八月甲辰，杨荣等到达京师。皇太子朱高炽当天派皇太孙朱瞻基前往开平迎接明成祖的灵柩。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年八月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3e8d82b3-281f-50f4-897e-e2beb61882ab"}, {"title": "夏原吉获释出狱，恢复原职", "description": "永乐22年（年号对照1424年）八月，夏原吉获释出狱，恢复原职。", "start_year": 1424, "end_year": 1424, "time_original": "永乐22年（年号对照1424年）八月；公元年核为1424年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "332ff296-16d2-588a-ace4-38b4add888d3"}, {"title": "吴中获释出狱", "description": "永乐22年（年号对照1424年）八月，吴中获释出狱。", "start_year": 1424, "end_year": 1424, "time_original": "永乐22年（年号对照1424年）八月；公元年核为1424年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "3b7bd37c-1266-549d-88c5-101d6faedab4"}, {"title": "朱高炽即皇帝位", "description": "永樂22年（1424年）八月，朱高炽即皇帝位。", "start_year": 1424, "end_year": 1424, "time_original": "永樂22年（1424年）八月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "6a758d06-3cf5-5853-a341-c88bfb86d8ba"}, {"title": "明仁宗大赦天下，定次年为洪熙元年", "description": "永乐二十二年八月，明仁宗朱高炽即位后大赦天下，规定次年启用洪熙年号。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ccb767bb-3993-59ed-a8e7-48fa09b12f03"}, {"title": "明仁宗叫停派遣西洋宝船等事务", "description": "永乐二十二年八月，明仁宗朱高炽即位后，叫停派遣西洋宝船、迤西购买马匹，以及在云南、交阯的采办。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0c664287-db40-52b9-acc1-83f7901bea2f"}, {"title": "郑亨等四将分镇大同、交阯、山海和辽东", "description": "永乐二十二年八月己未，明廷命郑亨、孟瑛、李隆和朱荣分别镇守大同、交阯、山海和辽东。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年八月己未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "236ee802-972d-5671-b91c-86f660d08137"}, {"title": "明廷恢复设置三公、三孤", "description": "永乐二十二年八月，明廷恢复三公、三孤等官，由公、侯、伯和各部尚书兼任。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0a11387e-de41-5a0a-9aa7-e2100eb3f3e0"}, {"title": "杨荣升任太常卿，仍兼原职", "description": "永樂22年（1424年）八月，杨荣升任太常卿，仍兼原职。", "start_year": 1424, "end_year": 1424, "time_original": "永樂22年（1424年）八月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "92aa4f0d-9ba0-5828-87bd-41a9e20f3db0"}, {"title": "金幼孜升任户部右侍郎，仍兼原职", "description": "永樂22年（1424年）八月，金幼孜升任户部右侍郎，仍兼原职。", "start_year": 1424, "end_year": 1424, "time_original": "永樂22年（1424年）八月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "4f95f823-0cf2-577d-ad33-ef371f84b3ec"}, {"title": "杨士奇升任礼部左侍郎，兼华盖殿大学士", "description": "永樂22年（1424年）八月，杨士奇升任礼部左侍郎，兼华盖殿大学士。", "start_year": 1424, "end_year": 1424, "time_original": "永樂22年（1424年）八月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "e99047a5-d065-597a-b59b-10e264fe45d8"}, {"title": "黄淮升任通政使，兼武英殿大学士", "description": "永樂22年（1424年），黄淮升任通政使，兼武英殿大学士。", "start_year": 1424, "end_year": 1424, "time_original": "永樂22年（1424年）", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "b17a5895-b228-58d5-9f28-119cb7962932"}, {"title": "杨溥出任翰林学士", "description": "永乐二十二年八月，朝廷任命杨溥为翰林学士。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bec98936-95dd-54b1-a2e5-91049089fe6c"}, {"title": "顾兴祖任总兵官，奉命赴广西出兵", "description": "永乐二十二年八月辛酉，镇远侯顾兴祖受任为总兵官，奉命征讨广西反抗明廷的当地居民。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年八月辛酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9eb2f621-8767-5079-865c-0f73b250b4b7"}, {"title": "明仁宗裁撤冗官", "description": "永乐二十二年八月甲子，朝廷裁撤多余官员。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年八月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b34040f1-b406-5d80-9835-f62cea063ce9"}, {"title": "朱高煦奉召赴京", "description": "永乐二十二年八月乙丑，朝廷召汉王朱高煦前往京师。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年八月乙丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "25e9a095-0e1f-55eb-a50c-81f9afdbc186"}, {"title": "明廷释放被罚入军籍的官吏回乡", "description": "永乐二十二年八月戊辰，朝廷让被贬谪编入军籍的官吏返回家乡。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年八月戊辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "05bcbc36-7a8c-5c54-81d3-c70916f2e117"}, {"title": "明廷规定文臣年满七十退休", "description": "永乐二十二年八月己巳，朝廷下诏，文臣年满七十可致仕。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年八月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a1747b66-3090-5313-bed9-803601c5009b"}, {"title": "方政在茶笼州败于黎利所部，伍云阵亡", "description": "永乐二十二年九月癸酉，交阯都指挥方政在茶笼州与黎利所部交战，明军战败，指挥同知伍云在战斗中身亡。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年九月癸酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3da305db-0f4f-528d-83b2-a1d9ec83e3c4"}, {"title": "黄福从交阯被召回", "description": "永乐22年（年号对照1424年）九月，黄福从交阯被召回。", "start_year": 1424, "end_year": 1424, "time_original": "永乐22年（年号对照1424年）九月；公元年核为1424年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "eb9f221a-2fff-5f53-9672-036657417703"}, {"title": "王彰镇抚河南", "description": "永乐22年（年号对照1424年）九月，王彰镇抚河南。", "start_year": 1424, "end_year": 1424, "time_original": "永乐22年（年号对照1424年）九月；公元年核为1424年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "14e83e9d-81a2-5b16-84c2-394077ef9425"}, {"title": "明廷命官署按价在产地购料，禁止摊派", "description": "永乐二十二年九月壬午，明廷命各官署到物料产地按价购买。摊派物料、使百姓受苦的官员要受追究。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年九月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0c77b25d-bd6a-5f83-a132-0abb0823f87c"}, {"title": "吕震请求结束服丧，明仁宗未准", "description": "永乐二十二年九月癸未，礼部尚书吕震请求结束服丧，明仁宗朱高炽没有同意。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年九月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "70f7db26-dc60-5621-a959-621cdef19dec"}, {"title": "明廷增加诸王年俸", "description": "永乐二十二年九月乙酉，明廷增加各王的年俸。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年九月乙酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d57b17ba-9262-5e9d-bf89-a6c5e91ca358"}, {"title": "萧奇等三十五名风宪官被调任州县", "description": "永乐二十二年九月丙戌，朝廷派给事中萧奇等三十五名风宪官出任州县官。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年九月丙戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "94d05e1b-9573-5f1a-b2f9-512f88e4e393"}, {"title": "黎利进攻清化，都指挥同知陈忠阵亡", "description": "永乐二十二年九月丁亥，黎利率部进攻清化，都指挥同知陈忠在交战中身亡。卷末校记说明，官职原脱「都」字。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年九月丁亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3b71b373-5938-5631-9116-fd9dc39b075f"}, {"title": "明廷设南京守备，任李隆担任", "description": "永乐二十二年九月戊子，朝廷首次设置南京守备一职，任命襄城伯李隆担任。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年九月戊子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fd53e293-0a6e-5cdb-a8af-1edbb0362140"}, {"title": "朝廷将京畿民户饲养的官马调拨给卫所", "description": "永乐二十二年九月乙未，明廷把原由京畿民户饲养的官马分配给各卫所。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年九月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5ca6ba14-f3f1-5b46-9b24-5c26625ed6c3"}, {"title": "明仁宗赐蹇义等银章，准其密奏政事过失", "description": "永乐二十二年九月戊戌，明仁宗给蹇义、杨士奇、杨荣、金幼孜各赐一枚刻有「绳愆纠缪」的银章，嘱咐他们发现政事缺失时用章密封奏报。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年九月戊戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3ea394d7-ba4d-5de5-a6fa-824fec316bad"}, {"title": "明廷停止向民间购金银，撤两京户部行用库", "description": "永乐二十二年十月壬寅，明廷停止向民间购买金银，撤销两京户部行用库。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c207b094-6efb-5666-a87f-815db52220e9"}, {"title": "明廷命各地都司、卫所修治城池", "description": "永乐二十二年十月癸卯，朝廷下诏，要求各地都司、卫所修治城池。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十月癸卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2ef2dd5e-0783-52db-9201-5b05c8a43a14"}, {"title": "明仁宗命各地雨情奏报到达后立即上呈", "description": "永乐二十二年十月戊申，通政使请求把各地雨情奏章交给给事中保管。明仁宗朱高炽认为，及时了解旱涝才能救济百姓，命收到报告即上呈。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十月戊申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "32703407-c128-5e74-9f55-c79423ddf80e"}, {"title": "明仁宗册立张氏为皇后", "description": "永乐二十二年十月己酉，明仁宗朱高炽立妃张氏为皇后。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十月己酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1a8e29d6-0258-5882-911c-85c082170a6c"}, {"title": "明仁宗立长子朱瞻基为皇太子", "description": "永乐二十二年十月壬子，明仁宗朱高炽立长子朱瞻基为皇太子。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4ef35abe-dccf-5171-830b-e80ac352f6c8"}, {"title": "明仁宗分封诸子为亲王", "description": "永乐二十二年十月，明仁宗朱高炽封瞻埈为郑王、瞻墉为越王、瞻墡为襄王、瞻堈为荆王、瞻墺为淮王、瞻塏为滕王、瞻垍为梁王、瞻埏为卫王。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "419e5b67-0c12-5994-841f-5f066e85be87"}, {"title": "明廷命官员荐举贤才，并严格执行荐举连坐制度", "description": "永乐二十二年十月乙卯，朝廷命中央和地方官员举荐人才，并严格执行举荐人的连坐制度。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十月乙卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9b07a5ab-e720-56b7-ba19-453043ae1865"}, {"title": "明廷规定三法司会同有关官员在承天门审录囚犯", "description": "永乐二十二年十月丁巳，朝廷命三法司会同大学士、各府部、通政司及六科的人在承天门审录囚犯，将做法写入法令。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十月丁巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fd9df491-2988-5326-a337-ce31c573be98"}, {"title": "明廷增加京官与军士的每月俸粮", "description": "永乐二十二年十月庚申，明廷增加京官和军士每月领取的俸粮。卷末校记记载，旧文误作当月已经出现的丁巳。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "75cf3689-993d-5dee-9cff-a2900cd86836"}, {"title": "徐永溍等二十名监生被任为给事中", "description": "永乐二十二年十月丁卯，朝廷提拔徐永溍等二十名监生为给事中。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fa3bfc0a-da4e-5321-9139-719e7b2ce732"}, {"title": "明仁宗赦免部分建文臣属家属，并归还田地", "description": "永乐二十二年十一月初一，明仁宗朱高炽下诏，赦免因建文诸臣获罪而被编入指定机构或没入功臣家为奴的人，使其恢复平民身份、取回田地。因上言而被贬去戍边的人也受同例宽免。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十一月壬申朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ea355811-3049-54e1-a6fb-f57ca6b85685"}, {"title": "明仁宗命官署报告扰民政令和灾情", "description": "永乐二十二年十一月癸酉，明仁宗下诏命主管官署逐条报告不便于民的政令，遇灾害而不立即申请救济的官员要受追究。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十一月癸酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "21efaf17-9f55-5665-ad69-8142a6fb5ace"}, {"title": "阿鲁台来贡马", "description": "永乐二十二年十一月，《明史》本纪记阿鲁台来向朝廷进献马匹。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3e809633-fdb4-5c5a-a0e0-d474a5adb20a"}, {"title": "明仁宗命臣下直言政事缺失", "description": "永乐二十二年十一月甲戌，明仁宗朱高炽下诏，请群臣指出当时政事中的缺失。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十一月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3b73feaf-b76e-5992-8922-61cac5e97405"}, {"title": "明廷赦免兀良哈", "description": "永乐二十二年十一月乙亥，明廷下令赦免兀良哈。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十一月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e02d3bcb-9773-5039-b9be-42bfe71ed094"}, {"title": "明廷命京畿各卫官军轮流进京操练", "description": "永乐二十二年十一月，朝廷命京畿附近各卫官军开始轮流到京师操练。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ff289936-3b23-5576-b2cf-7aab17405237"}, {"title": "明廷派御史巡视边境卫所", "description": "永乐二十二年十一月丙子，朝廷派御史出巡，查察边境卫所事务。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十一月丙子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "03c3f1d8-d2ad-5b8a-abe4-357e4bc13285"}, {"title": "明廷分派御史巡察各地官吏", "description": "永乐二十二年十一月癸未，朝廷分派御史巡视各地，考察官员表现。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十一月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "477b4d13-2481-5850-9ace-b772e74a4742"}, {"title": "明仁宗赐夏原吉「绳愆纠缪」银章", "description": "永乐二十二年十一月丙戌，明仁宗朱高炽赐户部尚书夏原吉一枚刻有「绳愆纠缪」的银章。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十一月丙戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "673bb754-0f83-5001-8b6c-a318e3001693"}, {"title": "明仁宗未准冬至受贺", "description": "永乐二十二年十一月己丑，礼部上奏，请明仁宗在冬至时接受朝贺，朱高炽未予准许。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十一月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6e241791-3705-57e3-bc03-9f0ecdd7e38b"}, {"title": "朝廷命各将加强边防", "description": "永乐二十二年十一月庚寅，朝廷命各将领严加防备边境。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十一月庚寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1bd63e7a-d59d-52ec-b07e-b5f646240426"}, {"title": "明廷禁止官署擅自征调屯田军士服役", "description": "永乐二十二年十一月辛卯，朝廷禁止主管官署擅自调用屯田军士服差役。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十一月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0c2fa4ce-2c97-55cd-ae0a-edbffaaeab27"}, {"title": "方政和陈智奉命共同镇守交阯", "description": "永乐二十二年十一月壬辰，朝廷命都督方政与荣昌伯陈智共同镇守交阯。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十一月壬辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e15a55a1-a182-59e5-8d52-a185a0ee6835"}, {"title": "明仁宗告诫蹇义等人警惕君主拒听直言", "description": "永乐二十二年十一月，明仁宗向蹇义、杨士奇、夏原吉、杨荣、金幼孜指出，君主拒听直言、臣下相互迎合，会使政事败坏，嘱咐众人以此为戒。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "501f68b2-0125-501a-909d-93bdb48b5ff2"}, {"title": "明仁宗宽免建文诸臣被罚全家戍边的外亲", "description": "永乐二十二年十二月癸卯，明廷宽免因建文诸臣获罪而全家被罚戍边的外亲。每家留一人继续戍守，其余释放回乡。卷末校记说明，此处为「外亲」。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十二月癸卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3ce3e113-8a68-5161-866b-e749aafce462"}, {"title": "明廷在奉天门公布各地三司官员姓名", "description": "永乐二十二年十二月辛亥，明廷在奉天门西侧张贴各地三司官员姓名。", "start_year": 1425, "end_year": 1425, "time_original": "永乐二十二年十二月辛亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5e26f9a6-8551-592f-881b-091011632876"}, {"title": "明廷豁免灾区税粮", "description": "永乐二十二年十二月癸丑，朝廷豁免受灾地区应缴的税粮。", "start_year": 1425, "end_year": 1425, "time_original": "永乐二十二年十二月癸丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "af34d3e2-8e7b-5bf8-aaaf-3678b8ff4929"}, {"title": "明成祖正式安葬在长陵", "description": "永乐二十二年十二月庚申，礼称文皇帝的朱棣安葬于长陵。", "start_year": 1425, "end_year": 1425, "time_original": "永乐二十二年十二月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2038531c-95d1-5d62-a547-b4dd030d7e69"}, {"title": "顾兴祖在平乐、浔州击败对抗明廷的部众", "description": "永乐二十二年十二月丙寅，镇远侯顾兴祖率军在平乐和浔州击败当地对抗明廷的部众。", "start_year": 1425, "end_year": 1425, "time_original": "永乐二十二年十二月丙寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b6239f47-af9b-5921-a73e-6e7d101bf9a6"}, {"title": "本纪汇记永乐二十二年多地入贡", "description": "永乐二十二年，于阗、琉球、占城、哈密、古麻剌朗、满剌加、苏禄和瓦剌入贡。本纪于年末合记来使。 按原历纪年，事情发生在公元1424至1425年之间。", "start_year": null, "end_year": null, "time_original": "永乐二十二年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "15fd1caf-2d75-5fe8-bed1-5bc5aaa4fc25"}, {"title": "朱高炽和朱高煦奉召回京", "description": "朝廷召世子朱高炽与高阳王朱高煦返回京师。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年正月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "76df15a5-4905-565c-9f5a-8366647fdd3b"}, {"title": "朱棣册立朱高炽为皇太子", "description": "朱棣立儿子朱高炽为皇太子，同时封朱高煦为汉王、朱高燧为赵王。", "start_year": 1404, "end_year": 1404, "time_original": "永乐二年四月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c87e8a77-7815-57c2-b44c-1f6c0b5f83ff"}, {"title": "黄淮被关入监狱", "description": "永樂12年（1414年）闰九月，黄淮被关入监狱。", "start_year": 1414, "end_year": 1414, "time_original": "永樂12年（1414年）闰九月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "e4a03a90-bf45-552a-ae5b-c62e10708c23"}]'::jsonb)
